#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>

/* Same struct as the candidate's. */
struct slot_header {
    int      valid;
    uint32_t version;
    uint32_t security_version;
    uint32_t trial_remaining;
    int      confirmed;
};

/* Provided by the candidate in solution.c */
int select_slot(const struct slot_header *a, const struct slot_header *b,
                uint32_t min_security_version);

static int read_slot(struct slot_header *s)
{
    return scanf("%d %" SCNu32 " %" SCNu32 " %" SCNu32 " %d",
                 &s->valid, &s->version, &s->security_version,
                 &s->trial_remaining, &s->confirmed) == 5;
}

int main(void)
{
    struct slot_header a, b;
    uint32_t floor_version;
    while (read_slot(&a) && read_slot(&b)
           && scanf("%" SCNu32, &floor_version) == 1) {
        printf("%d\n", select_slot(&a, &b, floor_version));
    }
    return 0;
}
